1	<script setup lang="ts">
2	/**
3	 * Gmail account status and lifecycle controls (Slices 02 + 03).
4	 *
5	 * Gmail remains read-only until authoritative `mutationAccess: enabled`; the explicit
6	 * upgrade disclosure explains Google's broader modify scope. Lifecycle commands
7	 * return acceptance, so button state follows the authoritative AccountStatus (plus a
8	 * transient busy flag), never an invented OAuth/sync success. Failures stay typed
9	 * and visible; the cached list/reader remain usable while sync is offline or
10	 * sign-in is required.
11	 *
12	 * Safety: plain text interpolation only — no HTML, no remote assets, no URLs.
13	 */
14	import type { AccountStatus, ConnectionState, MailError, MutationAccess } from '../lib/ipc/client';
15	import type { AccountAction } from '../composables/useMailbox';
16	import FullDate from './FullDate.vue';
17	
18	const props = defineProps<{
19	  status: AccountStatus;
20	  /** Transient in-flight lifecycle action, if any. */
21	  busy: AccountAction | null;
22	  transitioning?: boolean;
23	  actionError?: MailError | null;
24	}>();
25	
26	const emit = defineEmits<{
27	  connect: [];
28	  disconnect: [];
29	  sync: [];
30	  enableActions: [];
31	  cancelUpgrade: [];
32	}>();
33	
34	const CONNECTION_LABELS: Record<ConnectionState, string> = {
35	  not_configured: 'Not configured',
36	  disconnected: 'Disconnected',
37	  authenticating: 'Signing in…',
38	  connected: 'Connected',
39	  auth_required: 'Sign-in required',
40	};
41	
42	const SYNC_LABELS: Record<AccountStatus['sync']['state'], string> = {
43	  idle: 'Idle',
44	  syncing: 'Syncing…',
45	  error: 'Sync error',
46	};
47	
48	function connectionLabel(connection: ConnectionState): string {
49	  return CONNECTION_LABELS[connection];
50	}
51	
52	function accessLabel(access: MutationAccess | undefined): string {
53	  switch (access ?? 'read_only') {
54	    case 'read_only': return 'read-only';
55	    case 'upgrading': return 'Permission upgrade in progress';
56	    case 'enabled': return 'Mailbox actions enabled';
57	  }
58	}
59	
60	function describeError(error: MailError): string {
61	  switch (error.kind) {
62	    case 'not_configured':
63	      return 'Gmail is not configured on this device.';
64	    case 'auth_required':
65	      return 'Sign-in is required to continue syncing.';
66	    case 'auth_cancelled':
67	      return 'Sign-in was cancelled.';
68	    case 'auth_failed':
69	      return 'Sign-in failed.';
70	    case 'secrets_unavailable':
71	      return 'Secure credential storage is unavailable.';
72	    case 'network_unavailable':
73	      return 'The network is unavailable.';
74	    case 'rate_limited':
75	      return 'The provider is rate limiting; retrying with backoff.';
76	    case 'provider_unavailable':
77	      return 'The mail provider is temporarily unavailable.';
78	    case 'invalid_provider_response':
79	      return 'The provider returned an unexpected response.';
80	    case 'busy':
81	      return 'A sync is already in progress.';
82	    case 'permission_required':
83	      return 'Google did not grant mailbox-action permission; the account remains read-only.';
84	    case 'provider_rejected':
85	      return 'The provider rejected the mailbox action.';
86	    case 'outcome_unknown':
87	      return 'The provider outcome is unknown; review Activity before retrying.';
88	    case 'read_only':
89	      return 'Gmail is read-only; this action is unavailable.';
90	    case 'storage_unavailable':
91	      return 'Local storage is unavailable.';
92	    case 'not_found':
93	      return 'Not found.';
94	    case 'invalid_request':
95	      return 'Invalid request.';
96	    case 'request_id_conflict':
97	      return 'Conflicting request.';
98	    case 'profile_in_use':
99	      return 'The profile is in use by another window.';
100	    default:
101	      return 'unknown error';
102	  }
103	}
104	
105	function coverageText(): string {
106	  const sync = props.status.sync;
107	  if (!sync.initialSyncComplete) {
108	    return sync.coverageLimit > 0
109	      ? `Initial sync in progress: ${sync.cachedConversations} conversations cached; coverage is bounded to ${sync.coverageLimit} discovered conversations and may be incomplete.`
110	      : `Initial sync in progress: ${sync.cachedConversations} conversations cached so far.`;
111	  }
112	  if (sync.coverageLimit > 0) {
113	    return `The cached inbox view contains up to ${sync.coverageLimit} discovered conversations; additional inbox threads may be omitted.`;
114	  }
115	  return '';
116	}
117	
118	const showConnect = (): boolean =>
119	  props.status.connection === 'not_configured' ||
120	  props.status.connection === 'disconnected' ||
121	  props.status.connection === 'auth_required';
122	</script>
123	
124	<template>
125	  <section class="account-panel" aria-label="Account" data-test="account-panel">
126	    <div class="account-row">
127	      <span class="account-mode" data-test="account-mode">Gmail — {{ accessLabel(props.status.mutationAccess) }}</span>
128	      <span class="account-connection" data-test="account-connection">{{ connectionLabel(props.status.connection) }}</span>
129	    </div>
130	    <p v-if="props.status.account" class="account-email" data-test="account-email">
131	      {{ props.status.account.emailAddress }}
132	    </p>
133	    <p class="account-disposable" data-test="disposable-account-note">
134	      Disposable test account. Cached reading remains available during permission changes.
135	    </p>
136	    <p v-if="props.actionError" class="account-action-error" data-test="account-action-error" role="alert">
137	      Mailbox-action request: {{ describeError(props.actionError) }}
138	    </p>
139	    <template v-if="(props.status.mutationAccess ?? 'read_only') === 'read_only' && props.status.connection === 'connected'">
140	      <p class="account-upgrade-disclosure" data-test="action-upgrade-disclosure" role="note">
141	        Enable mailbox actions requests Google's broad Gmail modify permission, which can also allow sending and deleting mail.
142	        Email OS currently implements only Mark done / Mark not done, explicit Mark read / Mark unread and Star / Unstar; it does not send or delete mail.
143	      </p>
144	      <button
145	        type="button"
146	        data-test="enable-mailbox-actions"
147	        :disabled="props.busy !== null"
148	        @click="emit('enableActions')"
149	      >
150	        {{ props.busy === 'enable-actions' ? 'Requesting permission…' : 'Enable mailbox actions' }}
151	      </button>
152	    </template>
153	    <p v-else-if="props.status.mutationAccess === 'upgrading'" data-test="action-upgrading" role="status">
154	      Google permission upgrade in progress. Mail remains readable; actions stay disabled until access is verified.
155	    </p>
156	    <p v-else-if="props.status.mutationAccess === 'enabled'" data-test="actions-enabled" role="status">
157	      Mailbox actions are enabled for this account.
158	    </p>
159	    <button
160	      v-if="props.status.mutationAccess === 'upgrading'"
161	      type="button"
162	      data-test="cancel-action-upgrade"
163	      :disabled="props.busy !== null"
164	      @click="emit('cancelUpgrade')"
165	    >
166	      {{ props.busy === 'cancel-upgrade' ? 'Canceling permission request…' : 'Cancel permission upgrade' }}
167	    </button>
168	    <p class="account-disconnect-warning" data-test="disconnect-warning" role="note">
169	      Disconnect removes local pending actions and mail cache, but local drafts remain on this device and are accessible after reconnecting the same account. It does not undo confirmed Gmail changes or revoke Google's grant.
170	    </p>
171	    <p v-if="props.status.connection === 'not_configured'" class="account-notice" data-test="account-not-configured" role="note">
172	      Gmail is not configured on this device: no Google client credentials were found, so connecting is unavailable.
173	    </p>
174	    <p v-if="props.status.connection === 'auth_required'" class="account-notice" data-test="account-auth-required" role="note">
175	      Sign-in has expired. Cached conversations stay readable; reconnect to sync new mail.
176	    </p>
177	    <div class="account-row">
178	      <span class="account-sync" data-test="account-sync-state">{{ SYNC_LABELS[props.status.sync.state] }}</span>
179	      <span class="account-last-synced" data-test="account-last-synced"><template v-if="props.status.sync.lastSyncedAt">Last synced <FullDate :at="props.status.sync.lastSyncedAt" /></template><template v-else>Never synced</template></span>
180	    </div>
181	    <p
182	      v-if="props.status.sync.state === 'error' && props.status.sync.error"
183	      class="account-sync-error"
184	      data-test="account-sync-error"
185	      role="alert"
186	    >
187	      Last sync failed: {{ describeError(props.status.sync.error) }}
188	    </p>
189	    <p v-if="coverageText()" class="account-coverage" data-test="account-coverage">
190	      {{ coverageText() }}
191	    </p>
192	    <p class="account-cached" data-test="account-cached">
193	      {{ props.status.sync.cachedConversations }} conversation(s) cached locally.
194	    </p>
195	    <div class="account-actions">
196	      <button
197	        v-if="showConnect()"
198	        type="button"
199	        data-test="account-connect"
200	        :disabled="props.busy !== null || props.transitioning"
201	        @click="emit('connect')"
202	      >
203	        {{ props.status.connection === 'auth_required' ? 'Sign in again' : 'Connect' }}
204	      </button>
205	      <button
206	        v-if="props.status.account !== null || props.status.connection === 'auth_required' || props.status.connection === 'authenticating'"
207	        type="button"
208	        data-test="account-disconnect"
209	        :disabled="props.busy !== null || props.transitioning"
210	        @click="emit('disconnect')"
211	      >
212	        {{ props.status.connection === 'authenticating' ? 'Cancel sign-in' : 'Disconnect' }}
213	      </button>
214	      <button
215	        v-if="props.status.connection === 'connected'"
216	        type="button"
217	        data-test="account-sync"
218	        :disabled="props.busy !== null || props.status.sync.state === 'syncing'"
219	        @click="emit('sync')"
220	      >
221	        Sync now
222	      </button>
223	    </div>
224	  </section>
225	</template>
