82	<template>
83	  <section class="provider-destinations" aria-label="Provider destinations" @keydown="keydown">
84	    <p>Read-only provider snapshots. No automatic read changes. Label and Move are not available in this increment.</p>
85	    <template v-if="!destination">
86	      <label>Find a destination <input v-model="query" type="search" /></label>
87	      <div class="destination-toolbar">
88	        <button :disabled="busy" @click="loadCatalog()">Refresh catalog</button>
89	        <button :disabled="busy" @click="loadCatalog(true)">Use saved catalog</button>
90	      </div>
91	      <p v-if="catalog">{{ cached ? 'Saved' : 'Provider' }} catalog · <FullDate :at="catalog.fetchedAt" /></p>
92	      <ul class="destination-catalog">
