94	      </ul>
95	      <p v-if="catalog && !matches.length">No destinations match this catalog search.</p>
96	      <button v-if="shown < matches.length" @click="shown += 9">Show more destinations</button>
97	    </template>
98	    <template v-else>
99	      <button v-if="!opened" @click="backToCatalog()">Back to destinations</button>
100	      <h3>{{ destination.name }}</h3>
101	      <p v-if="destination.id === 'DRAFT'">Provider Drafts are read-only mail snapshots, separate from editable Local drafts. Nothing here syncs local drafts.</p>
102	      <p v-if="destination.id === 'ALL_MAIL'">All Mail excludes Spam and Trash.</p>
103	      <div v-show="!opened">
104	        <div class="destination-toolbar">
105	          <button :disabled="busy" @click="loadPage(destination)">Refresh first page</button>
106	          <button :disabled="busy" @click="loadPage(destination, null, true)">Use latest saved page</button>
107	        </div>
108	        <p v-if="page" role="status">{{ cached ? 'Saved local snapshot' : 'Provider page snapshot' }} · <FullDate :at="page.fetchedAt" /> · {{ page.conversations.length }} loaded on this page. Mailbox total unknown.</p>
109	        <div ref="list" class="destination-list" tabindex="-1" aria-label="Destination conversations">
110	          <button v-for="conversation in page?.conversations ?? []" :key="conversation.ref.accountId + ':' + conversation.ref.conversationId" class="destination-row" :disabled="busy" @click="open(conversation, $event)">{{ conversation.subject || '(No subject)' }}</button>
111	          <p v-if="page && !page.conversations.length">No conversations on this page. This is not a mailbox-completeness claim.</p>
112	        </div>
113	        <button v-if="page?.nextCursor && !cached" :disabled="busy" @click="loadPage(destination, page.nextCursor)">Next provider page (up to 25)</button>
114	        <p v-if="cached && page?.nextCursor">More provider pages may exist; refresh online to continue.</p>
115	      </div>
116	      <article v-if="opened" aria-label="Destination conversation" class="destination-reader">
117	        <button ref="readerBack" data-test="destination-back" @click="backToList()">Back to {{ destination.name }}</button>
118	        <h3>{{ opened.subject }}</h3>
119	        <p>Snapshot only — provider state may have changed since the page was fetched.</p>
120	        <p v-if="opened.retainedSnapshotAt">Retained local recovery snapshot · <FullDate :at="opened.retainedSnapshotAt" /></p>
121	        <p v-if="opened.contextComplete === false || opened.unsupportedReason">Incomplete or unsupported content: {{ opened.unsupportedReason ?? 'Some messages unavailable' }}</p>
122	        <section v-for="message in opened.messages" :key="message.id">
123	          <h4>{{ message.from.displayName || message.from.mailbox }}</h4>
124	          <p>{{ message.from.mailbox }} · <FullDate :at="message.sentAt" /></p>
125	          <p v-if="message.to.length" class="message-to">To {{ message.to.map((t) => t.displayName ?? t.mailbox).join(', ') }}</p>
126	          <pre>{{ message.bodyText }}</pre>
127	        </section>
128	      </article>
129	    </template>
130	    <p v-if="busy" role="status">Loading bounded provider data…</p>
131	    <p v-if="error" role="alert">Could not load {{ destination ? 'destination page' : 'catalog' }}: {{ error }}. Previous snapshots, if shown, are unchanged. Try Refresh or explicitly use saved data.</p>
132	  </section>
133	</template>
134	
